index asset_items_account asset_items: CREATE INDEX asset_items_account ON asset_items(account_id)
index booking_documents_account booking_documents: CREATE INDEX booking_documents_account ON booking_documents(account_id)
index booking_documents_booking booking_documents: CREATE INDEX booking_documents_booking ON booking_documents(booking_id)
index booking_documents_info booking_documents: CREATE INDEX booking_documents_info ON booking_documents(doc_date DESC,id DESC,booking_id,account_id,title,doc_type,mime_type,file_name,length(pdf_bytes),source_url,created_at)
index booking_documents_source booking_documents: CREATE UNIQUE INDEX booking_documents_source ON booking_documents(source_url)WHERE source_url != ''
index categories_unique_name categories: CREATE UNIQUE INDEX categories_unique_name ON categories(IFNULL(parent_id,0),name)WHERE deleted_ms IS NULL
index categories_uuid categories: CREATE UNIQUE INDEX categories_uuid ON categories(uuid)
index holdings_account holdings: CREATE INDEX holdings_account ON holdings(account_id)
index loan_links_loan loan_links: CREATE INDEX loan_links_loan ON loan_links(loan_account_id)
index rules_uuid rules: CREATE UNIQUE INDEX rules_uuid ON rules(uuid)
index split_cat transaction_splits: CREATE INDEX split_cat ON transaction_splits(category_id)
index split_tx transaction_splits: CREATE INDEX split_tx ON transaction_splits(transaction_id)
index sync_log_ts sync_log: CREATE INDEX sync_log_ts ON sync_log(ts_ms)
index tx_account_category transactions: CREATE INDEX tx_account_category ON transactions(account_id,category_id,deleted_ms)
index tx_account_checked transactions: CREATE INDEX tx_account_checked ON transactions(account_id,checked,deleted_ms)
index tx_account_date transactions: CREATE INDEX tx_account_date ON transactions(account_id,booking_date DESC)
index tx_category transactions: CREATE INDEX tx_category ON transactions(category_id)
index tx_date_id transactions: CREATE INDEX tx_date_id ON transactions(booking_date DESC,id DESC)
index tx_import_fp transactions: CREATE INDEX tx_import_fp ON transactions(account_id,import_fp)WHERE import_fp != ''
index tx_rule transactions: CREATE INDEX tx_rule ON transactions(rule_id,deleted_ms)
index tx_salary_marked transactions: CREATE INDEX tx_salary_marked ON transactions(counterparty_iban)WHERE salary_flag = 1
table account_groups account_groups: CREATE TABLE account_groups(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,sf_symbol TEXT NOT NULL DEFAULT 'folder',sort_order INTEGER NOT NULL DEFAULT 0)
table accounts accounts: CREATE TABLE accounts(id INTEGER PRIMARY KEY,connection_id INTEGER REFERENCES bank_connections(id)ON DELETE SET NULL,group_id INTEGER NOT NULL REFERENCES account_groups(id),external_ref TEXT NOT NULL DEFAULT '',name TEXT NOT NULL,bank_name TEXT NOT NULL DEFAULT '',owner TEXT NOT NULL DEFAULT '',iban TEXT NOT NULL DEFAULT '',account_number TEXT NOT NULL DEFAULT '',currency TEXT NOT NULL DEFAULT 'EUR',kind TEXT NOT NULL DEFAULT 'checking',balance_cents INTEGER NOT NULL DEFAULT 0,balance_date TEXT NOT NULL DEFAULT '',sf_symbol TEXT NOT NULL DEFAULT 'building.columns',sort_order INTEGER NOT NULL DEFAULT 0,initial_balance_cents INTEGER,access_revoked INTEGER NOT NULL DEFAULT 0,user_group_uuid TEXT,user_sort_order INTEGER NOT NULL DEFAULT 0,placement_ms INTEGER NOT NULL DEFAULT 0,name_ms INTEGER NOT NULL DEFAULT 0,color_hex TEXT,color_ms INTEGER NOT NULL DEFAULT 0,symbol_ms INTEGER NOT NULL DEFAULT 0,archived_unix INTEGER,archived_ms INTEGER NOT NULL DEFAULT 0,created_ms INTEGER NOT NULL DEFAULT 0,deleted_ms INTEGER,balance_derived INTEGER NOT NULL DEFAULT 0,UNIQUE(connection_id,external_ref))
table asset_items asset_items: CREATE TABLE asset_items(id INTEGER PRIMARY KEY,uuid TEXT NOT NULL UNIQUE,account_id INTEGER NOT NULL REFERENCES accounts(id)ON DELETE CASCADE,name TEXT NOT NULL,price_source TEXT NOT NULL,weight_grams REAL NOT NULL DEFAULT 0,purity_permille REAL NOT NULL DEFAULT 1000,interpolation TEXT NOT NULL DEFAULT 'step',purchase_date TEXT NOT NULL,purchase_price_cents INTEGER,note TEXT NOT NULL DEFAULT '',created_ms INTEGER NOT NULL DEFAULT 0,symbol TEXT NOT NULL DEFAULT '',changed_ms INTEGER NOT NULL DEFAULT 0,deleted_ms INTEGER)
table asset_price_fetch asset_price_fetch: CREATE TABLE asset_price_fetch(symbol TEXT PRIMARY KEY,from_date TEXT NOT NULL,to_date TEXT NOT NULL,fetched_unix INTEGER NOT NULL)
table asset_prices asset_prices: CREATE TABLE asset_prices(symbol TEXT NOT NULL,date TEXT NOT NULL,price_cents INTEGER NOT NULL,source TEXT NOT NULL DEFAULT 'api',PRIMARY KEY(symbol,date))
table asset_quantities asset_quantities: CREATE TABLE asset_quantities(item_id INTEGER NOT NULL REFERENCES asset_items(id)ON DELETE CASCADE,date TEXT NOT NULL,quantity REAL NOT NULL,changed_ms INTEGER NOT NULL DEFAULT 0,deleted_ms INTEGER,PRIMARY KEY(item_id,date))
table asset_values asset_values: CREATE TABLE asset_values(item_id INTEGER NOT NULL REFERENCES asset_items(id)ON DELETE CASCADE,date TEXT NOT NULL,value_cents INTEGER NOT NULL,changed_ms INTEGER NOT NULL DEFAULT 0,deleted_ms INTEGER,PRIMARY KEY(item_id,date))
table bank_connections bank_connections: CREATE TABLE bank_connections(id INTEGER PRIMARY KEY,connector TEXT NOT NULL,display_name TEXT NOT NULL,login_name TEXT NOT NULL DEFAULT '',bank_code TEXT NOT NULL DEFAULT '',sf_symbol TEXT NOT NULL DEFAULT 'building.columns',state_json TEXT NOT NULL DEFAULT '{}',last_sync_unix INTEGER,created_unix INTEGER NOT NULL DEFAULT(strftime('%s','now')),created_ms INTEGER NOT NULL DEFAULT 0,deleted_ms INTEGER)
table booking_documents booking_documents: CREATE TABLE booking_documents(id INTEGER PRIMARY KEY,booking_id INTEGER REFERENCES transactions(id)ON DELETE SET NULL,account_id INTEGER REFERENCES accounts(id)ON DELETE SET NULL,title TEXT NOT NULL DEFAULT '',doc_type TEXT NOT NULL DEFAULT 'beleg',mime_type TEXT NOT NULL DEFAULT 'application/pdf',file_name TEXT NOT NULL DEFAULT '',pdf_bytes BLOB NOT NULL,source_url TEXT NOT NULL DEFAULT '',doc_date TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL DEFAULT(strftime('%s','now')),exported_at INTEGER)
table categories categories: CREATE TABLE categories(id INTEGER PRIMARY KEY,parent_id INTEGER REFERENCES categories(id)ON DELETE CASCADE,name TEXT NOT NULL,sf_symbol TEXT NOT NULL DEFAULT 'tag',color_hex TEXT NOT NULL DEFAULT '#8E8E93',budget_cents INTEGER,sort_order INTEGER NOT NULL DEFAULT 0,uuid TEXT,name_ms INTEGER NOT NULL DEFAULT 0,parent_ms INTEGER NOT NULL DEFAULT 0,symbol_ms INTEGER NOT NULL DEFAULT 0,color_ms INTEGER NOT NULL DEFAULT 0,budget_ms INTEGER NOT NULL DEFAULT 0,order_ms INTEGER NOT NULL DEFAULT 0,deleted_ms INTEGER,merged_into TEXT)
table holdings holdings: CREATE TABLE holdings(id INTEGER PRIMARY KEY,account_id INTEGER NOT NULL REFERENCES accounts(id)ON DELETE CASCADE,isin TEXT NOT NULL DEFAULT '',wkn TEXT NOT NULL DEFAULT '',name TEXT NOT NULL DEFAULT '',quantity REAL NOT NULL DEFAULT 0,current_price_cents INTEGER NOT NULL DEFAULT 0,purchase_price_cents INTEGER NOT NULL DEFAULT 0,value_cents INTEGER NOT NULL DEFAULT 0)
table loan_links loan_links: CREATE TABLE loan_links(transaction_id INTEGER PRIMARY KEY REFERENCES transactions(id)ON DELETE CASCADE,loan_account_id INTEGER NOT NULL REFERENCES accounts(id)ON DELETE CASCADE,source TEXT NOT NULL DEFAULT 'manual')
table loan_terms loan_terms: CREATE TABLE loan_terms(account_id INTEGER PRIMARY KEY REFERENCES accounts(id)ON DELETE CASCADE,anchor_date TEXT NOT NULL,anchor_balance_cents INTEGER NOT NULL,interest_rate_ppm INTEGER,match_expr TEXT NOT NULL DEFAULT '')
table merchant_domain_overrides merchant_domain_overrides: CREATE TABLE merchant_domain_overrides(merchant_key TEXT PRIMARY KEY,domain TEXT NOT NULL,updated_at INTEGER NOT NULL DEFAULT(strftime('%s','now')))
table merchant_logo_cache merchant_logo_cache: CREATE TABLE merchant_logo_cache(domain TEXT PRIMARY KEY,image_bytes BLOB,updated_at INTEGER NOT NULL DEFAULT(strftime('%s','now')),source TEXT NOT NULL DEFAULT '')
table opening_balances opening_balances: CREATE TABLE opening_balances(account_id INTEGER PRIMARY KEY REFERENCES accounts(id)ON DELETE CASCADE,opening_date TEXT NOT NULL DEFAULT '',opening_cents INTEGER,updated_ms INTEGER NOT NULL DEFAULT 0)
table recurring_series recurring_series: CREATE TABLE recurring_series(id INTEGER PRIMARY KEY,series_key TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'manual',interval TEXT NOT NULL DEFAULT 'monthly',custom_dates TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL DEFAULT(strftime('%s','now')))
table rules rules: CREATE TABLE rules(id INTEGER PRIMARY KEY,name TEXT NOT NULL,category_id INTEGER NOT NULL REFERENCES categories(id)ON DELETE CASCADE,field TEXT NOT NULL DEFAULT 'any',match_kind TEXT NOT NULL DEFAULT 'keyword',pattern TEXT NOT NULL,case_sensitive INTEGER NOT NULL DEFAULT 0,min_amount_cents INTEGER,max_amount_cents INTEGER,account_id INTEGER REFERENCES accounts(id)ON DELETE CASCADE,priority INTEGER NOT NULL DEFAULT 100,enabled INTEGER NOT NULL DEFAULT 1,uuid TEXT,updated_ms INTEGER NOT NULL DEFAULT 0,deleted_ms INTEGER,merged_into TEXT)
table settings settings: CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,is_secret INTEGER NOT NULL DEFAULT 0)
table sqlite_sequence sqlite_sequence: CREATE TABLE sqlite_sequence(name,seq)
table sync_log sync_log: CREATE TABLE sync_log(id INTEGER PRIMARY KEY AUTOINCREMENT,ts_ms INTEGER NOT NULL,connection_id INTEGER,connection_name TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT 'manual',outcome TEXT NOT NULL,message TEXT NOT NULL DEFAULT '',imported INTEGER NOT NULL DEFAULT 0)
table transaction_splits transaction_splits: CREATE TABLE transaction_splits(id INTEGER PRIMARY KEY,transaction_id INTEGER NOT NULL REFERENCES transactions(id)ON DELETE CASCADE,category_id INTEGER REFERENCES categories(id)ON DELETE SET NULL,amount_cents INTEGER NOT NULL,note TEXT NOT NULL DEFAULT '')
table transactions transactions: CREATE TABLE transactions(id INTEGER PRIMARY KEY,account_id INTEGER NOT NULL REFERENCES accounts(id)ON DELETE CASCADE,external_id TEXT NOT NULL,booking_date TEXT NOT NULL,value_date TEXT NOT NULL DEFAULT '',amount_cents INTEGER NOT NULL,currency TEXT NOT NULL DEFAULT 'EUR',counterparty TEXT NOT NULL DEFAULT '',counterparty_iban TEXT NOT NULL DEFAULT '',purpose TEXT NOT NULL DEFAULT '',booking_text TEXT NOT NULL DEFAULT '',category_id INTEGER REFERENCES categories(id)ON DELETE SET NULL,category_source TEXT NOT NULL DEFAULT 'none',rule_id INTEGER REFERENCES rules(id)ON DELETE SET NULL,checked INTEGER NOT NULL DEFAULT 0,imported_unix INTEGER NOT NULL DEFAULT(strftime('%s','now')),note TEXT NOT NULL DEFAULT '',import_fp TEXT NOT NULL DEFAULT '',purpose_code TEXT NOT NULL DEFAULT '',gvc TEXT NOT NULL DEFAULT '',salary_flag INTEGER,category_ms INTEGER NOT NULL DEFAULT 0,note_ms INTEGER NOT NULL DEFAULT 0,checked_ms INTEGER NOT NULL DEFAULT 0,text_ms INTEGER NOT NULL DEFAULT 0,splits_ms INTEGER NOT NULL DEFAULT 0,deleted_ms INTEGER,end_to_end_id TEXT NOT NULL DEFAULT '',mandate_id TEXT NOT NULL DEFAULT '',creditor_id TEXT NOT NULL DEFAULT '',UNIQUE(account_id,external_id))
table transfer_templates transfer_templates: CREATE TABLE transfer_templates(id INTEGER PRIMARY KEY,name TEXT NOT NULL,recipient_name TEXT NOT NULL,recipient_iban TEXT NOT NULL,recipient_bic TEXT NOT NULL DEFAULT '',default_amount_cents INTEGER,default_purpose TEXT NOT NULL DEFAULT '')
table user_groups user_groups: CREATE TABLE user_groups(uuid TEXT PRIMARY KEY,name TEXT NOT NULL,sf_symbol TEXT NOT NULL DEFAULT 'folder',sort_order INTEGER NOT NULL DEFAULT 0,include_in_total INTEGER NOT NULL DEFAULT 1,updated_ms INTEGER NOT NULL DEFAULT 0,name_ms INTEGER NOT NULL DEFAULT 0,symbol_ms INTEGER NOT NULL DEFAULT 0,total_ms INTEGER NOT NULL DEFAULT 0,order_ms INTEGER NOT NULL DEFAULT 0,deleted_ms INTEGER,merged_into TEXT,parent_uuid TEXT,parent_ms INTEGER NOT NULL DEFAULT 0,color_hex TEXT,color_ms INTEGER NOT NULL DEFAULT 0)
